// ── SCE Accepted Subset §2.15: what a host observes of a sce-static machine ──

/// The published variables (`sce:direction="out"`) as one owned value, in
/// declaration order.
#[derive(Debug, Clone, PartialEq)]
#[allow(non_snake_case)]
pub struct RecordListParentData {
    pub told: u32,
    pub shown: RecordListParentToldRecord,
    pub others: Vec<RecordListParentToldValueRecord>,
    pub refused: Option<RecordListParentRefusedRecord>,
    pub refused_count: u32,
}

/// What a host observes: the full active configuration — every active state,
/// each region of a `<parallel>` included — and the published variables,
/// taken together between two host calls, which is a macrostep boundary (W3C
/// SCXML Appendix D). `truncated` is `true` when that macrostep was stopped at
/// the microstep ceiling, so the configuration is not a stable one. Owned: a
/// host holding one keeps what it saw whatever the machine does next.
#[derive(Debug, Clone, PartialEq)]
pub struct RecordListParentSnapshot {
    pub configuration: RecordListParentConfiguration,
    pub data: RecordListParentData,
    pub truncated: bool,
}

/// The snapshot of a running machine, as an extension of the runtime's
/// `Engine` (a foreign type, so a local trait — the `Inject` shape).
pub trait RecordListParentObserve {
    /// The machine as the host sees it now: one [`RecordListParentSnapshot`],
    /// never a state between two microsteps.
    fn snapshot(&self) -> RecordListParentSnapshot;
}

impl RecordListParentObserve for Engine<RecordListParentPolicy> {
    fn snapshot(&self) -> RecordListParentSnapshot {
        let policy = self.policy();
        RecordListParentSnapshot {
            configuration: self.get_active_states(),
            data: RecordListParentData {
                told: policy.told,
                shown: policy.shown.clone(),
                others: policy.others.clone(),
                refused: policy.refused,
                refused_count: policy.refused_count,
            },
            truncated: self.last_macrostep_truncated(),
        }
    }
}

