    // NL→IR Item C1 Path A: store the current event's typed `_event.data`
    // payload so native transition guards can read it without a script
    // engine. Called by the engine's pop loop for every dequeued event;
    // events injected without a typed payload carry the `#[default] None`
    // variant, against which the variant-specific guards simply fail.
    fn populate_event_payload(&mut self, payload: &Self::Payload) {
        self.pending_payload = payload.clone();
    }

    // NL→IR Item C1 Path A: …and when no typed payload rode with the event,
    // read that view out of the `data` every other producer fills — `<send>`
    // with `<param>`, an invoke forwarding either way, autoforward, BasicHTTP,
    // mesh. A payload that does not read as this event's schema is returned as
    // a refusal, which the engine raises as `error.execution`.
    fn lift_event_payload(
        &mut self,
        event: Self::Event,
        data: &str,
    ) -> ::core::result::Result<(), ::sce_rust_runtime::event_payload::PayloadRefusal> {
        // A typed payload already bound the view, so the producer was the inject
        // seam and there is nothing to read out of `data`.
        if self.pending_payload != RecordListParentPayload::None {
            return Ok(());
        }
        match event {
            RecordListParentEvent::RecordListClear => {
                let fields = ::sce_rust_runtime::event_payload::PayloadFields::decode(data)?;
                self.pending_payload = RecordListParentPayload::RecordListClear(
                    RecordListParentRecordListClearPayload {
                        id: fields.unsigned::<u32>("id")?,
                        field: fields.unsigned::<u16>("field")?,
                        now: fields.signed64("now")?,
                        more: fields.truth("more")?,
                    },
                );
            }
            RecordListParentEvent::RecordListEdit => {
                let fields =
                    ::sce_rust_runtime::event_payload::PayloadFields::decode_with_defaults(
                        data,
                        "{\"more\":false}",
                    )?;
                self.pending_payload = RecordListParentPayload::RecordListEdit(
                    RecordListParentRecordListEditPayload {
                        id: fields.unsigned::<u32>("id")?,
                        field: fields.unsigned::<u16>("field")?,
                        value: fields.signed64("value")?,
                        text: fields.text("text")?,
                        now: fields.signed64("now")?,
                        more: fields.truth("more")?,
                    },
                );
            }
            RecordListParentEvent::RecordListJoin => {
                let fields = ::sce_rust_runtime::event_payload::PayloadFields::decode(data)?;
                self.pending_payload = RecordListParentPayload::RecordListJoin(
                    RecordListParentRecordListJoinPayload {
                        node: fields.unsigned64("node")?,
                        hub: fields.truth("hub")?,
                    },
                );
            }
            RecordListParentEvent::RecordListRefused => {
                let fields = ::sce_rust_runtime::event_payload::PayloadFields::decode(data)?;
                self.pending_payload = RecordListParentPayload::RecordListRefused(
                    RecordListParentRecordListRefusedPayload {
                        id: fields.unsigned::<u32>("id")?,
                        field: fields.unsigned::<u16>("field")?,
                        kind: match fields.text("kind")?.as_str() {
                            "edit" => RecordListParentRecordCommandEnum::Edit,
                            "clear" => RecordListParentRecordCommandEnum::Clear,
                            "retire" => RecordListParentRecordCommandEnum::Retire,
                            other => {
                                return Err(::sce_rust_runtime::event_payload::PayloadRefusal::new(
                                    format!("kind ({other}) is not a variant of record_command"),
                                ))
                            }
                        },
                        reason: match fields.text("reason")?.as_str() {
                            "notWriter" => RecordListParentRecordRefusalEnum::NotWriter,
                            "noRoomForValue" => RecordListParentRecordRefusalEnum::NoRoomForValue,
                            "noRoomForHistory" => {
                                RecordListParentRecordRefusalEnum::NoRoomForHistory
                            }
                            "noRoomForDigest" => RecordListParentRecordRefusalEnum::NoRoomForDigest,
                            "textTooLong" => RecordListParentRecordRefusalEnum::TextTooLong,
                            "changeTooLarge" => RecordListParentRecordRefusalEnum::ChangeTooLarge,
                            "registerNamedTwice" => {
                                RecordListParentRecordRefusalEnum::RegisterNamedTwice
                            }
                            "clockExhausted" => RecordListParentRecordRefusalEnum::ClockExhausted,
                            other => {
                                return Err(::sce_rust_runtime::event_payload::PayloadRefusal::new(
                                    format!("reason ({other}) is not a variant of record_refusal"),
                                ))
                            }
                        },
                    },
                );
            }
            RecordListParentEvent::RecordListRegister => {
                let fields = ::sce_rust_runtime::event_payload::PayloadFields::decode(data)?;
                self.pending_payload = RecordListParentPayload::RecordListRegister(
                    RecordListParentRecordListRegisterPayload {
                        id: fields.unsigned::<u32>("id")?,
                        field: fields.unsigned::<u16>("field")?,
                        count: fields.unsigned::<u32>("count")?,
                        value: fields.signed64("value")?,
                        text: fields.text("text")?,
                        wallTime: fields.signed64("wallTime")?,
                        counter: fields.unsigned::<u32>("counter")?,
                        nodeId: fields.unsigned64("nodeId")?,
                    },
                );
            }
            RecordListParentEvent::RecordListRetire => {
                let fields = ::sce_rust_runtime::event_payload::PayloadFields::decode(data)?;
                self.pending_payload = RecordListParentPayload::RecordListRetire(
                    RecordListParentRecordListRetirePayload {
                        id: fields.unsigned::<u32>("id")?,
                        now: fields.signed64("now")?,
                        more: fields.truth("more")?,
                    },
                );
            }
            RecordListParentEvent::RecordListRole => {
                let fields = ::sce_rust_runtime::event_payload::PayloadFields::decode(data)?;
                self.pending_payload = RecordListParentPayload::RecordListRole(
                    RecordListParentRecordListRolePayload {
                        node: fields.unsigned64("node")?,
                        role: fields.unsigned::<u8>("role")?,
                    },
                );
            }
            RecordListParentEvent::RecordListRoom => {
                let fields = ::sce_rust_runtime::event_payload::PayloadFields::decode(data)?;
                self.pending_payload = RecordListParentPayload::RecordListRoom(
                    RecordListParentRecordListRoomPayload {
                        values: fields.unsigned::<u32>("values")?,
                        history: fields.unsigned::<u32>("history")?,
                        digest: fields.unsigned::<u32>("digest")?,
                    },
                );
            }
            RecordListParentEvent::RecordListSupersede => {
                let fields =
                    ::sce_rust_runtime::event_payload::PayloadFields::decode_with_defaults(
                        data,
                        "{\"parts\":1,\"atWallTime\":\"0\",\"atCounter\":0}",
                    )?;
                self.pending_payload = RecordListParentPayload::RecordListSupersede(
                    RecordListParentRecordListSupersedePayload {
                        id: fields.unsigned::<u32>("id")?,
                        field: fields.unsigned::<u16>("field")?,
                        wallTime: fields.signed64("wallTime")?,
                        counter: fields.unsigned::<u32>("counter")?,
                        nodeId: fields.unsigned64("nodeId")?,
                        by: fields.unsigned64("by")?,
                        parts: fields.unsigned::<u32>("parts")?,
                        atWallTime: fields.signed64("atWallTime")?,
                        atCounter: fields.unsigned::<u32>("atCounter")?,
                    },
                );
            }
            RecordListParentEvent::RecordListValue => {
                let fields = ::sce_rust_runtime::event_payload::PayloadFields::decode(data)?;
                self.pending_payload = RecordListParentPayload::RecordListValue(
                    RecordListParentRecordListValuePayload {
                        id: fields.unsigned::<u32>("id")?,
                        field: fields.unsigned::<u16>("field")?,
                        ordinal: fields.unsigned::<u32>("ordinal")?,
                        value: fields.signed64("value")?,
                        text: fields.text("text")?,
                        wallTime: fields.signed64("wallTime")?,
                        counter: fields.unsigned::<u32>("counter")?,
                        nodeId: fields.unsigned64("nodeId")?,
                    },
                );
            }
            RecordListParentEvent::RecordListWrite => {
                let fields =
                    ::sce_rust_runtime::event_payload::PayloadFields::decode_with_defaults(
                        data,
                        "{\"parts\":1}",
                    )?;
                self.pending_payload = RecordListParentPayload::RecordListWrite(
                    RecordListParentRecordListWritePayload {
                        id: fields.unsigned::<u32>("id")?,
                        field: fields.unsigned::<u16>("field")?,
                        value: fields.signed64("value")?,
                        text: fields.text("text")?,
                        wallTime: fields.signed64("wallTime")?,
                        counter: fields.unsigned::<u32>("counter")?,
                        nodeId: fields.unsigned64("nodeId")?,
                        parts: fields.unsigned::<u32>("parts")?,
                    },
                );
            }
            _ => {}
        }
        Ok(())
    }

