    // §scxml-3.10.2: a <history>'s default transition content, run after its
    // parent's onentry (and after the parent's own <initial> content) when the
    // history was taken with nothing recorded. The engine asks for it by the
    // entry set's defaultHistoryContent answer; a history that restored what it
    // recorded runs nothing.

    // W3C SCXML 3.8: Execute <onexit> actions for a state
    #[doc = "SCE-MAP: record_list_parent.scxml:40 :: _machine"]
    // SCE-MAP: record_list_parent.scxml:40 :: _machine
    fn execute_exit_actions(
        &mut self,
        state: Self::State,
        engine: &mut sce_rust_runtime::Engine<Self>,
        configuration_before_exit: &[Self::State],
    ) {
        // §scxml-D-exitStates orders one state's exit as onexit, then
        // cancelInvoke, then configuration.delete(s), so `In(s)` inside s's
        // own handler is true: the deactivation is the LAST step here.
        match state {
            _ => {}
        }
        // W3C SCXML 6.4: Cancel pending invokes and cleanup active children on
        // state exit — after the onexit above, per §scxml-D-exitStates.
        match state {
            RecordListParentState::Holding => {
                // W3C SCXML 6.4: Cancel pending invokes for exited state.
                // Covers §scxml-6.4.1 entries: an invoke whose state exits
                // before the macrostep ends never runs, so it raises nothing.
                sce_rust_runtime::invoke::cancel_invokes_for_state(
                    &mut self.pending_invokes,
                    RecordListParentState::Holding,
                );
                // W3C SCXML 6.4: Cleanup running static child 'list'
                if self.child_list.is_some() {
                    // §scxml-6.4: cancelling raises nothing in this session —
                    // the spec defines no `cancel.invoke` event, and a document
                    // that named one used to receive it here.
                    //
                    // §scxml-D-exitInterpreter: a cancelled session is exited —
                    // its states' `<onexit>` run — before it is dropped. What
                    // that exit sends to `#_parent` lands in the child's own
                    // queue, which is dropped with it undrained (§scxml-6.4
                    // cancel-drop, test252).
                    if let Some(mut child) = self.child_list.take() {
                        child.stop();
                        // Child sessions in Mesh (SCE_MESH.md): the session
                        // ended, after the child stopped, so what it sent while
                        // stopping was handed to its router first.
                        child.detach_mesh();
                    }
                }
                self.active_invokes.remove("list");
                self.pending_done_invoke_list = false;
            }
            _ => {}
        }
    }

